# (All classes and properties have rdfs:label and rdfs:comment as required)

@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-ontology>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "A deeply structured ontology for modeling UN/EDIFACT invoice messages, segments, and organizational roles, aligned with D96A and EN 16931-1." .

#################################################################
# CLASSES
#################################################################
:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level envelope that contains one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An EDIFACT invoice message (INVOIC)." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "The Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "The Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice, containing dates and references." ;
    rdfs:subClassOf :Segment .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section with line items." ;
    rdfs:subClassOf :Segment .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section with totals and tax." ;
    rdfs:subClassOf :Segment .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business organization involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in a transaction." .
    owl:disjointUnionOf (:BuyerRole :DeliveryPartyRole) .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in an invoice transaction." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in an invoice transaction." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or logical address related to an organization." ;
    owl:disjointUnionOf (:WarehouseAddress :HeadquartersAddress) .

:WarehouseAddress a owl:Class ;
    rdfs:label "Warehouse Address" ;
    rdfs:comment "Address of a warehouse related to an organization." ;
    rdfs:subClassOf :Address .

:HeadquartersAddress a owl:Class ;
    rdfs:label "Headquarters Address" ;
    rdfs:comment "Headquarters address of an organization." ;
    rdfs:subClassOf :Address .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in the invoice." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the invoice, referencing an item and its price." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with an item or invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for the document." .

:DocumentDate a owl:Class ;
    rdfs:label "Document Date" ;
    rdfs:comment "The date of the invoice document." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations or documents." .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A global location number for organizations." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which an invoice can be assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating the invoice according to rules or standards." .

:P2PItem a owl:Class ;
    rdfs:label "P2P-O Item" ;
    rdfs:comment "A core item class from the Purchase-to-Pay Ontology." ;
    rdfs:subClassOf :Item .

:P2POrganization a owl:Class ;
    rdfs:label "P2P-O Organization" ;
    rdfs:comment "A core organization class from the Purchase-to-Pay Ontology." ;
    rdfs:subClassOf :Organization .

#################################################################
# PIVOT/REIFICATION CLASSES
#################################################################
:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A reification class linking an organization to a role in a specific context." .

:LineItemDetail a owl:Class ;
    rdfs:label "Line Item Detail" ;
    rdfs:comment "A reification class capturing detailed attributes of a line item." .

#################################################################
# OBJECT PROPERTIES
#################################################################
:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Associates a message with its segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasSection a owl:ObjectProperty ;
    rdfs:label "has section" ;
    rdfs:comment "Associates an invoice message with its sections: header, detail, summary." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Associates the detail section with line items." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Associates a line item with the item being sold." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Associates a line item with its price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Associates the summary section with tax information." ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links summary to total invoice amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount .

:hasReferenceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links header to document reference number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber .

:hasDocumentDate a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "Links header to document date." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :DocumentDate .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an invoice message to involved organizations." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization .

:playsRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "plays role" ;
    rdfs:comment "Links a role assignment to a role." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole .

:assignedTo a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned to" ;
    rdfs:comment "Links a role assignment to an organization." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its addresses." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Links invoice to the relevant business process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .

:isValidatedBy a owl:ObjectProperty ;
    rdfs:label "is validated by" ;
    rdfs:comment "Links an invoice message to a validation constraint." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint .

:hasMandatoryIdentifier a owl:ObjectProperty ;
    rdfs:label "has mandatory identifier" ;
    rdfs:comment "Links invoice message to mandatory identifiers." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Identifier .

:hasP2PItem a owl:ObjectProperty ;
    rdfs:label "has P2P item" ;
    rdfs:comment "Links line item to P2P-O item." ;
    rdfs:domain :LineItem ;
    rdfs:range :P2PItem .

:hasP2POrganization a owl:ObjectProperty ;
    rdfs:label "has P2P organization" ;
    rdfs:comment "Links organization to P2P-O organization." ;
    rdfs:domain :Organization ;
    rdfs:range :P2POrganization .

#################################################################
# DATA PROPERTIES
#################################################################
:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "The organization's global location number." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasIdentifier a owl:DatatypeProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Generic identifier for organizations." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasName a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has name" ;
    rdfs:comment "The name of the organization." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "The net price of an item." ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Quantity of the line item." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasTaxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "The total tax amount." ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string .

#################################################################
# RESTRICTIONS & GCAs
#################################################################
:InvoiceMessage rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :HeaderSection ] ,
                                 [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :DetailSection ] ,
                                 [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :SummarySection ] .

:OrganizationRoleAssignment rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :playsRole ; owl:allValuesFrom :AgentRole ] .

:Organization rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:allValuesFrom :Address ] .

