    rdfs:label "has P2P organization" ;
    rdfs:comment "Links organization to P2P-O organization." ;
    rdfs:domain :Organization ;
    rdfs:range :P2POrganization ;
    owl:inverseOf :isP2POrganizationOf .

:isP2POrganizationOf a owl:ObjectProperty ;
    rdfs:label "is P2P organization of" ;
    rdfs:comment "Inverse of hasP2POrganization." ;
    rdfs:domain :P2POrganization ;
    rdfs:range :Organization ;
    owl:inverseOf :hasP2POrganization .

# Pivot class LineItemDetail now connected
:detailsLineItem a owl:ObjectProperty ;
    rdfs:label "details line item" ;
    rdfs:comment "Connects LineItemDetail to the LineItem it details." ;
    rdfs:domain :LineItemDetail ;
    rdfs:range :LineItem ;
    owl:inverseOf :isDetailedBy .

:isDetailedBy a owl:ObjectProperty ;
    rdfs:label "is detailed by" ;
    rdfs:comment "Inverse of detailsLineItem." ;
    rdfs:domain :LineItem ;
    rdfs:range :LineItemDetail ;
    owl:inverseOf :detailsLineItem .

:detailsItem a owl:ObjectProperty ;
    rdfs:label "details item" ;
    rdfs:comment "Connects LineItemDetail to the Item it details." ;
    rdfs:domain :LineItemDetail ;
    rdfs:range :Item ;
    owl:inverseOf :isItemDetailedBy .

:isItemDetailedBy a owl:ObjectProperty ;
    rdfs:label "is item detailed by" ;
    rdfs:comment "Inverse of detailsItem." ;
    rdfs:domain :Item ;
    rdfs:range :LineItemDetail ;
    owl:inverseOf :detailsItem .

#################################################################
# DATA PROPERTIES
#################################################################
:hasGlobalLocationNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has Global Location Number" ;
    rdfs:comment "The organization's global location number." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasIdentifier a owl:DatatypeProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Generic identifier for organizations." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasName a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has name" ;
    rdfs:comment "The name of the organization." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:hasNetPrice a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "The net price of an item." ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Quantity of the line item." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasTaxAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "The total tax amount." ;
    rdfs:domain :Tax ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range xsd:string .

#################################################################
# RESTRICTIONS & GCAs
#################################################################
:InvoiceMessage rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :HeaderSection ] ,
                                 [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :DetailSection ] ,
                                 [ a owl:Restriction ; owl:onProperty :hasSection ; owl:someValuesFrom :SummarySection ] .

:OrganizationRoleAssignment rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :playsRole ; owl:allValuesFrom :AgentRole ] .

:Organization rdfs:subClassOf [ a owl:Restriction ; owl:onProperty :hasAddress ; owl:allValuesFrom :Address ] .

#################################################################
# ANNOTATIONS
#################################################################
# (All classes and properties have rdfs:label and rdfs:comment as required)
"}

