:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "The Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "The Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The header section of an invoice, containing dates and references." ;
    rdfs:subClassOf :Segment .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The detail section with line items." ;
    rdfs:subClassOf :Segment .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The summary section with totals and tax." ;
    rdfs:subClassOf :Segment .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business organization involved in the invoice." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in a transaction." ;
    owl:disjointUnionOf ( :BuyerRole :DeliveryPartyRole ) .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "The role of buyer in an invoice transaction." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "The role of delivery party in an invoice transaction." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A physical or logical address related to an organization." ;
    owl:disjointUnionOf ( :WarehouseAddress :HeadquartersAddress ) .

:WarehouseAddress a owl:Class ;
    rdfs:label "Warehouse Address" ;
    rdfs:comment "Address of a warehouse related to an organization." ;
    rdfs:subClassOf :Address .

:HeadquartersAddress a owl:Class ;
    rdfs:label "Headquarters Address" ;
    rdfs:comment "Headquarters address of an organization." ;
    rdfs:subClassOf :Address .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "An item sold in the invoice." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "A line item in the invoice, referencing an item and its price." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with an item or invoice." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for the document." .

:DocumentDate a owl:Class ;
    rdfs:label "Document Date" ;
    rdfs:comment "The date of the invoice document." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "A generic identifier for organizations or documents." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which an invoice can be assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating the invoice according to rules or standards." .

:P2PItem a owl:Class ;
    rdfs:label "P2P-O Item" ;
    rdfs:comment "A core item class from the Purchase-to-Pay Ontology." ;
    rdfs:subClassOf :Item .

:P2POrganization a owl:Class ;
    rdfs:label "P2P-O Organization" ;
    rdfs:comment "A core organization class from the Purchase-to-Pay Ontology." ;
    rdfs:subClassOf :Organization .

