#################################################################
:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an interchange envelope to its contained message." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Associates a message with its segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasSection a owl:ObjectProperty ;
    rdfs:label "has section" ;
    rdfs:comment "Associates an invoice message with its sections: header, detail, summary." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Segment ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:label "is section of" ;
    rdfs:comment "Inverse of hasSection." ;
    rdfs:domain :Segment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSection .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Associates the detail section with line items." ;
    rdfs:domain :DetailSection ;
    rdfs:range :LineItem ;
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:label "is line item of" ;
    rdfs:comment "Inverse of hasLineItem." ;
    rdfs:domain :LineItem ;
    rdfs:range :DetailSection ;
    owl:inverseOf :hasLineItem .

:hasItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has item" ;
    rdfs:comment "Associates a line item with the item being sold." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:inverseOf :isItemOfLineItem .

:isItemOfLineItem a owl:ObjectProperty ;
    rdfs:label "is item of line item" ;
    rdfs:comment "Inverse of hasItem." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    owl:inverseOf :hasItem .

:hasPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Associates a line item with its price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:inverseOf :isPriceOfLineItem .

:isPriceOfLineItem a owl:ObjectProperty ;
    rdfs:label "is price of line item" ;
    rdfs:comment "Inverse of hasPrice." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    owl:inverseOf :hasPrice .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Associates the summary section with tax information." ;
    rdfs:domain :SummarySection ;
    rdfs:range :Tax ;
    owl:inverseOf :isTaxOfSummary .

:isTaxOfSummary a owl:ObjectProperty ;
    rdfs:label "is tax of summary" ;
    rdfs:comment "Inverse of hasTax." ;
    rdfs:domain :Tax ;
    rdfs:range :SummarySection ;
    owl:inverseOf :hasTax .

:hasInvoiceAmount a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Links summary to total invoice amount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount ;
    owl:inverseOf :isInvoiceAmountOfSummary .

:isInvoiceAmountOfSummary a owl:ObjectProperty ;
    rdfs:label "is invoice amount of summary" ;
    rdfs:comment "Inverse of hasInvoiceAmount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection ;
    owl:inverseOf :hasInvoiceAmount .

:hasReferenceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links header to document reference number." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber ;
    owl:inverseOf :isReferenceNumberOfHeader .

:isReferenceNumberOfHeader a owl:ObjectProperty ;
    rdfs:label "is reference number of header" ;
    rdfs:comment "Inverse of hasReferenceNumber." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :hasReferenceNumber .

:hasDocumentDate a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "Links header to document date." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :DocumentDate ;
    owl:inverseOf :isDocumentDateOfHeader .

:isDocumentDateOfHeader a owl:ObjectProperty ;
    rdfs:label "is document date of header" ;
    rdfs:comment "Inverse of hasDocumentDate." ;
    rdfs:domain :DocumentDate ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :hasDocumentDate .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an invoice message to involved organizations." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse of involvesOrganization." ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :involvesOrganization .

:playsRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "plays role" ;
    rdfs:comment "Links a role assignment to a role." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRolePlayedInAssignment .

:isRolePlayedInAssignment a owl:ObjectProperty ;
    rdfs:label "is role played in assignment" ;
    rdfs:comment "Inverse of playsRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :playsRole .

:assignedTo a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "assigned to" ;
    rdfs:comment "Links a role assignment to an organization." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :hasRoleAssignment .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Inverse of assignedTo." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :assignedTo .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an organization to its addresses." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOfOrganization .

:isAddressOfOrganization a owl:ObjectProperty ;
    rdfs:label "is address of organization" ;
    rdfs:comment "Inverse of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasBusinessProcess a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Links invoice to the relevant business process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:label "is business process of" ;
    rdfs:comment "Inverse of hasBusinessProcess." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasBusinessProcess .

:isValidatedBy a owl:ObjectProperty ;
    rdfs:label "is validated by" ;
    rdfs:comment "Links an invoice message to a validation constraint." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    owl:inverseOf :validates .

:validates a owl:ObjectProperty ;
    rdfs:label "validates" ;
    rdfs:comment "Inverse of isValidatedBy." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :isValidatedBy .

:hasMandatoryIdentifier a owl:ObjectProperty ;
    rdfs:label "has mandatory identifier" ;
    rdfs:comment "Links invoice message to mandatory identifiers." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Identifier ;
    owl:inverseOf :isMandatoryIdentifierOf .

:isMandatoryIdentifierOf a owl:ObjectProperty ;
    rdfs:label "is mandatory identifier of" ;
    rdfs:comment "Inverse of hasMandatoryIdentifier." ;
    rdfs:domain :Identifier ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasMandatoryIdentifier .

:hasP2PItem a owl:ObjectProperty ;
    rdfs:label "has P2P item" ;
    rdfs:comment "Links line item to P2P-O item." ;
    rdfs:domain :LineItem ;
    rdfs:range :P2PItem ;
    owl:inverseOf :isP2PItemOfLineItem .

