@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice-story>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Story Ontology" ;
    rdfs:comment "Ontology representing the structure of EDIFACT INVOIC messages, segments, and business semantics for procurement scenarios as described in the story." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope that contains EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:INVOICMessage a owl:Class ;
    rdfs:subClassOf :Message ;
    rdfs:label "INVOIC Message" ;
    rdfs:comment "An EDIFACT INVOIC message for invoices." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGMSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment, identifies the document." .

:NADSegment a owl:Class ;
    rdfs:subClassOf :Segment ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment, provides participant details." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element in an EDIFACT segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element in an EDIFACT segment." .

:Section a owl:Class ;
    rdfs:label "Section" ;
    rdfs:comment "A generic section within an INVOIC message (Header, Detail, or Summary)." .

:HeaderSection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Header Section" ;
    rdfs:comment "Header section of an invoice message, contains document dates and reference numbers." .

:DetailSection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Detail Section" ;
    rdfs:comment "Detail section of an invoice message, lists line items." .

:SummarySection a owl:Class ;
    rdfs:subClassOf :Section ;
    rdfs:label "Summary Section" ;
    rdfs:comment "Summary section of an invoice message, provides totals." .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice document within the INVOIC message." .

:InvoiceLine a owl:Class ;
    rdfs:label "Invoice Line" ;
    rdfs:comment "A line item within an invoice." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "An organization involved in the transaction (buyer, seller, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the context of an invoice (e.g., Buyer, Supplier, Delivery Party)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier assigned to an organization (e.g., VAT, DUNS)." .

:GlobalLocationNumber a owl:Class ;
    rdfs:subClassOf :Identifier ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A GLN identifier for organizations." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service sold in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price value associated with an item or invoice line." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "Tax information for the invoice." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validating the invoice structure and content." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A reification class linking an organization to a role in the context of a specific invoice." .

#################################################################
# Disjointness
#################################################################

:InterchangeEnvelope owl:disjointWith :Message, :Segment, :CompositeDataElement, :SimpleDataElement, :Invoice, :Organization, :AgentRole, :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Message owl:disjointWith :Segment, :CompositeDataElement, :SimpleDataElement, :Invoice, :Organization, :AgentRole, :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Segment owl:disjointWith :CompositeDataElement, :SimpleDataElement, :Invoice, :Organization, :AgentRole, :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:CompositeDataElement owl:disjointWith :SimpleDataElement, :Invoice, :Organization, :AgentRole, :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:SimpleDataElement owl:disjointWith :Invoice, :Organization, :AgentRole, :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Invoice owl:disjointWith :Organization, :AgentRole, :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Organization owl:disjointWith :AgentRole, :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:AgentRole owl:disjointWith :Address, :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Address owl:disjointWith :Identifier, :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Identifier owl:disjointWith :Item, :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Item owl:disjointWith :Price, :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Price owl:disjointWith :Tax, :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:Tax owl:disjointWith :BusinessProcess, :ValidationConstraint, :RoleAssignment, :Section .
:BusinessProcess owl:disjointWith :ValidationConstraint, :RoleAssignment, :Section .
:ValidationConstraint owl:disjointWith :RoleAssignment, :Section .
:RoleAssignment owl:disjointWith :Section .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an InterchangeEnvelope to the contained Message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "The Message is contained in an InterchangeEnvelope." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of" ;
    rdfs:comment "A Segment is part of a Message." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :Section ;
    rdfs:label "has section" ;
    rdfs:comment "Links an INVOICMessage to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Section ;
    rdfs:range :INVOICMessage ;
    rdfs:label "is section of" ;
    rdfs:comment "A Section is part of an INVOICMessage." .

:hasInvoice a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :Invoice ;
    rdfs:label "has invoice" ;
    rdfs:comment "Links an INVOICMessage to an Invoice." ;
    owl:inverseOf :isInvoiceOf .

:isInvoiceOf a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :INVOICMessage ;
    rdfs:label "is invoice of" ;
    rdfs:comment "An Invoice is part of an INVOICMessage." .

:hasLine a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :InvoiceLine ;
    rdfs:label "has line" ;
    rdfs:comment "Links an Invoice to its InvoiceLines." ;
    owl:inverseOf :isLineOf .

:isLineOf a owl:ObjectProperty ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :Invoice ;
    rdfs:label "is line of" ;
    rdfs:comment "An InvoiceLine is part of an Invoice." .

:hasOrganization a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    rdfs:label "has organization" ;
    rdfs:comment "Links an Invoice to involved Organizations." ;
    owl:inverseOf :isOrganizationIn .

:isOrganizationIn a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    rdfs:label "is organization in" ;
    rdfs:comment "The Organization is involved in the Invoice." .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an Organization to its RoleAssignments." ;
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "The RoleAssignment is assigned to an Organization." .

:playsRole a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    rdfs:label "plays role" ;
    rdfs:comment "Links a RoleAssignment to an AgentRole." ;
    owl:inverseOf :isRolePlayedInAssignment .

:isRolePlayedInAssignment a owl:ObjectProperty ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    rdfs:label "is role played in assignment" ;
    rdfs:comment "An AgentRole is played in a RoleAssignment." .

:inContextOfInvoice a owl:ObjectProperty ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Invoice ;
    rdfs:label "in context of invoice" ;
    rdfs:comment "Links a RoleAssignment to the Invoice context." ;
    owl:inverseOf :hasRoleAssignmentInContext .

:hasRoleAssignmentInContext a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :RoleAssignment ;
    rdfs:label "has role assignment in context" ;
    rdfs:comment "An Invoice has a RoleAssignment in its context." .

:hasAddress a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Addresses." ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    rdfs:label "is address of" ;
    rdfs:comment "The Address is associated with an Organization." .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an Organization to its Identifiers." ;
    owl:inverseOf :isIdentifierOf .

:isIdentifierOf a owl:ObjectProperty ;
    rdfs:domain :Identifier ;
    rdfs:range :Organization ;
    rdfs:label "is identifier of" ;
    rdfs:comment "The Identifier is assigned to an Organization." .

:hasGLN a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links an Organization to its Global Location Number (GLN)." ;
    owl:inverseOf :isGLNOf .

:isGLNOf a owl:ObjectProperty ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    rdfs:label "is GLN of" ;
    rdfs:comment "The GLN is assigned to an Organization." .

:hasItem a owl:ObjectProperty ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :Item ;
    rdfs:label "has item" ;
    rdfs:comment "Links an InvoiceLine to an Item." ;
    owl:inverseOf :isItemOfLine .

:isItemOfLine a owl:ObjectProperty ;
    rdfs:domain :Item ;
    rdfs:range :InvoiceLine ;
    rdfs:label "is item of line" ;
    rdfs:comment "The Item is included in an InvoiceLine." .

:hasNetPrice a owl:ObjectProperty ;
    rdfs:domain :InvoiceLine ;
    rdfs:range :Price ;
    rdfs:label "has net price" ;
    rdfs:comment "Links an InvoiceLine to its net Price." ;
    owl:inverseOf :isNetPriceOfLine .

:isNetPriceOfLine a owl:ObjectProperty ;
    rdfs:domain :Price ;
    rdfs:range :InvoiceLine ;
    rdfs:label "is net price of line" ;
    rdfs:comment "The Price is the net price of an InvoiceLine." .

:hasTax a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :Tax ;
    rdfs:label "has tax" ;
    rdfs:comment "Links an Invoice to its Tax information." ;
    owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
    rdfs:domain :Tax ;
    rdfs:range :Invoice ;
    rdfs:label "is tax of" ;
    rdfs:comment "The Tax is related to an Invoice." .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :ValidationConstraint ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Links an Invoice to ValidationConstraints for SHACL validation." ;
    owl:inverseOf :isValidationConstraintOf .

:isValidationConstraintOf a owl:ObjectProperty ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :Invoice ;
    rdfs:label "is validation constraint of" ;
    rdfs:comment "The ValidationConstraint is associated with an Invoice." .

:isValidForBusinessProcess a owl:ObjectProperty ;
    rdfs:domain :Invoice ;
    rdfs:range :BusinessProcess ;
    rdfs:label "is valid for business process" ;
    rdfs:comment "Links an Invoice to a BusinessProcess." ;
    owl:inverseOf :hasInvoiceValidFor .

:hasInvoiceValidFor a owl:ObjectProperty ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :Invoice ;
    rdfs:label "has invoice valid for" ;
    rdfs:comment "The BusinessProcess has an Invoice valid for it." .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a Segment to its CompositeDataElements." ;
