:hasTotalAmount a owl:DatatypeProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:decimal ;
    rdfs:label "has total amount" ;
    rdfs:comment "The total amount for an Invoice." .

:hasInvoiceNumber a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number for an Invoice." .

:hasDocumentDate a owl:DatatypeProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "has document date" ;
    rdfs:comment "The document date for an Invoice (ISO 8601 string)." .

:hasReferenceNumber a owl:DatatypeProperty ;
    rdfs:domain :Invoice ;
    rdfs:range xsd:string ;
    rdfs:label "has reference number" ;
    rdfs:comment "The reference number for an Invoice." .

:hasLabel a owl:DatatypeProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range xsd:string ;
    rdfs:label "has label" ;
    rdfs:comment "Label for a SimpleDataElement." .

:hasValue a owl:DatatypeProperty ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range xsd:string ;
    rdfs:label "has value" ;
    rdfs:comment "Value of a SimpleDataElement." .

#################################################################
# Property Characteristics
#################################################################

:containsMessage a owl:FunctionalProperty .
:hasGLN a owl:FunctionalProperty .
:hasInvoiceNumber a owl:FunctionalProperty .

#################################################################
# Complex Axioms & Restrictions
#################################################################

:Invoice a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasInvoiceNumber ; owl:cardinality "1"^^xsd:nonNegativeInteger ]
            [ a owl:Restriction ; owl:onProperty :hasLine ; owl:minCardinality "1"^^xsd:nonNegativeInteger ]
        )
    ] .

:RoleAssignment a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :playsRole ; owl:someValuesFrom :AgentRole ]
            [ a owl:Restriction ; owl:onProperty :inContextOfInvoice ; owl:someValuesFrom :Invoice ]
        )
    ] .

:Organization a owl:Class ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            [ a owl:Restriction ; owl:onProperty :hasRoleAssignment ; owl:someValuesFrom :RoleAssignment ]
        )
    ] .

#################################################################
# End of ontology
#################################################################
