:BusinessProcess owl:disjointWith :ValidationConstraint, :RoleAssignment, :Section .
:ValidationConstraint owl:disjointWith :RoleAssignment, :Section .
:RoleAssignment owl:disjointWith :Section .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an InterchangeEnvelope to the contained Message." ;
    owl:inverseOf :isContainedInEnvelope .

:isContainedInEnvelope a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    rdfs:label "is contained in envelope" ;
    rdfs:comment "Inverse of containsMessage." .

:hasSegment a owl:ObjectProperty ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse of hasSegment." .

:hasSection a owl:ObjectProperty ;
    rdfs:domain :INVOICMessage ;
    rdfs:range :Section ;
    rdfs:label "has section" ;
    rdfs:comment "Links an INVOICMessage to its header, detail, and summary sections." ;
    owl:inverseOf :isSectionOf .

:isSectionOf a owl:ObjectProperty ;
    rdfs:domain :Section ;
    rdfs:range :INVOICMessage ;
    rdfs:label "is section of" ;
