    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse property of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasGlobalLocationNumber a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has global location number" ;
    rdfs:comment "Relates an Organization to its GlobalLocationNumber." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    owl:inverseOf :isGlobalLocationNumberOf .

:isGlobalLocationNumberOf a owl:ObjectProperty ;
    rdfs:label "is global location number of" ;
    rdfs:comment "Inverse property of hasGlobalLocationNumber." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    owl:inverseOf :hasGlobalLocationNumber .

:hasHeaderSection a owl:ObjectProperty ;
    rdfs:label "has header section" ;
    rdfs:comment "Relates an Invoice to its HeaderSection." ;
    rdfs:domain :Invoice ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:label "is header section of" ;
    rdfs:comment "Inverse property of hasHeaderSection." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasHeaderSection .

:hasDetailSection a owl:ObjectProperty ;
    rdfs:label "has detail section" ;
    rdfs:comment "Relates an Invoice to its DetailSection." ;
    rdfs:domain :Invoice ;
    rdfs:range :DetailSection ;
    owl:inverseOf :isDetailSectionOf .

:isDetailSectionOf a owl:ObjectProperty ;
