    rdfs:label "address line" ;
    rdfs:comment "A line of text in an address." ;
    rdfs:domain :Address ;
    rdfs:range xsd:string .

:locationNumber a owl:DatatypeProperty ;
    rdfs:label "location number" ;
    rdfs:comment "The identifier value of a GlobalLocationNumber." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range xsd:string .

:priceValue a owl:DatatypeProperty ;
    rdfs:label "price value" ;
    rdfs:comment "The net price value for a line item." ;
    rdfs:domain :Price ;
    rdfs:range xsd:decimal .

:quantityValue a owl:DatatypeProperty ;
    rdfs:label "quantity value" ;
    rdfs:comment "The quantity value for a line item." ;
    rdfs:domain :Quantity ;
    rdfs:range xsd:integer .

:taxAmountValue a owl:DatatypeProperty ;
    rdfs:label "tax amount value" ;
    rdfs:comment "The value of the tax amount." ;
    rdfs:domain :TaxAmount ;
    rdfs:range xsd:decimal .

:invoiceAmountValue a owl:DatatypeProperty ;
    rdfs:label "invoice amount value" ;
    rdfs:comment "The value of the total invoice amount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range xsd:decimal .

:referenceNumberValue a owl:DatatypeProperty ;
    rdfs:label "reference number value" ;
    rdfs:comment "The value of a reference number (e.g., invoice number)." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range xsd:string .

:documentDateValue a owl:DatatypeProperty ;
    rdfs:label "document date value" ;
    rdfs:comment "The value of a document date (in string format)." ;
    rdfs:domain :DocumentDate ;
    rdfs:range xsd:string .

:roleIdentifier a owl:DatatypeProperty ;
    rdfs:label "role identifier" ;
    rdfs:comment "The identifier for a specific agent role (e.g. code for Buyer or DeliveryParty)." ;
    rdfs:domain :AgentRole ;
    rdfs:range xsd:string .

#################################################################
# Disjointness and Equivalence
#################################################################

:BuyerRole owl:disjointWith :DeliveryPartyRole .
:HeadquartersAddress owl:disjointWith :WarehouseAddress .

#################################################################
# Complex Axioms and Restrictions
#################################################################

:BuyerRole owl:equivalentClass [
    a owl:Restriction ;
    owl:onProperty :hasRole ;
    owl:allValuesFrom :AgentRole
] .

:InvoiceLineItemDetail owl:equivalentClass [
    a owl:Restriction ;
    owl:onProperty :hasPrice ;
    owl:someValuesFrom :Price
] .

[ a owl:Restriction ;
    owl:onProperty :hasRole ;
    owl:someValuesFrom :AgentRole ;
    rdfs:subClassOf :OrganizationRoleAssignment
] .
"}

args.owl_content:
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology/edifact-invoice>
    a owl:Ontology ;
    rdfs:label "EDIFACT Invoice Ontology" ;
    rdfs:comment "Ontology for modeling the structure and semantics of EDIFACT invoice messages (D96A) including envelopes, messages, segments, organizations, roles, and line items." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message such as INVOIC, contained within an InterchangeEnvelope." .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within a message, such as BGM or NAD, composed of composite and simple data elements." .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment, grouping multiple simple elements." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A basic data element within a composite or segment, representing atomic values." .

:Invoice a owl:Class ;
    rdfs:label "Invoice" ;
    rdfs:comment "An invoice document represented in the EDIFACT INVOIC message format." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A party involved in the invoice, such as buyer, supplier, or delivery party." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization in the context of an invoice (e.g., Buyer, DeliveryParty)." ;
    owl:disjointUnionOf ( :BuyerRole :DeliveryPartyRole ) .

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "A specific agent role indicating the organization is acting as buyer." ;
    rdfs:subClassOf :AgentRole .

:DeliveryPartyRole a owl:Class ;
    rdfs:label "Delivery Party Role" ;
    rdfs:comment "A specific agent role indicating the organization is acting as delivery party." ;
    rdfs:subClassOf :AgentRole .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address related to an organization." .

:HeadquartersAddress a owl:Class ;
    rdfs:label "Headquarters Address" ;
    rdfs:comment "The main address of an organization." ;
    rdfs:subClassOf :Address .

:WarehouseAddress a owl:Class ;
    rdfs:label "Warehouse Address" ;
    rdfs:comment "The address of an organization's warehouse." ;
    rdfs:subClassOf :Address .

:GlobalLocationNumber a owl:Class ;
    rdfs:label "Global Location Number" ;
    rdfs:comment "A globally unique location identifier for organizations." .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An item listed on the invoice, representing goods or services sold." ;
    rdfs:subClassOf :InvoiceLineItemDetail .

:P2PItem a owl:Class ;
    rdfs:label "P2P Item" ;
    rdfs:comment "An item as defined in the Purchase-to-Pay Ontology (P2P-O), subclass of LineItem." ;
    rdfs:subClassOf :LineItem .

:HeaderSection a owl:Class ;
    rdfs:label "Header Section" ;
    rdfs:comment "The section of the invoice containing general document information (dates, references)." .

:DetailSection a owl:Class ;
    rdfs:label "Detail Section" ;
    rdfs:comment "The section of the invoice listing line items and their details." .

:SummarySection a owl:Class ;
    rdfs:label "Summary Section" ;
    rdfs:comment "The section of the invoice summarizing totals such as tax and invoice amount." .

:InvoiceLineItemDetail a owl:Class ;
    rdfs:label "Invoice Line Item Detail" ;
    rdfs:comment "A pivot class reifying the relationship between a line item, its price, and quantity for the invoice detail section." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "The net price of a line item on the invoice." .

:Quantity a owl:Class ;
    rdfs:label "Quantity" ;
    rdfs:comment "The number of units for a line item on the invoice." .

:TaxAmount a owl:Class ;
    rdfs:label "Tax Amount" ;
    rdfs:comment "The total tax amount for the invoice." .

:InvoiceAmount a owl:Class ;
    rdfs:label "Invoice Amount" ;
    rdfs:comment "The total amount of the invoice." .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number such as an invoice number." .

:DocumentDate a owl:Class ;
    rdfs:label "Document Date" ;
    rdfs:comment "A date associated with the invoice document (issue, due, etc.)." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice can be assigned." .

:P2POrganization a owl:Class ;
    rdfs:label "P2P Organization" ;
    rdfs:comment "An organization as defined in the Purchase-to-Pay Ontology (P2P-O), subclass of Organization." ;
    rdfs:subClassOf :Organization .

:OrganizationRoleAssignment a owl:Class ;
    rdfs:label "Organization Role Assignment" ;
    rdfs:comment "A pivot class reifying the assignment of a role to an organization." .

#################################################################
# Properties
#################################################################

# Object Properties

:containsMessage a owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Relates an InterchangeEnvelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .
    # Removed owl:TransitiveProperty due to pitfall P29

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Relates a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Inverse property of hasSegment." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Relates a Segment to its CompositeDataElements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :isCompositeElementOf .

:isCompositeElementOf a owl:ObjectProperty ;
    rdfs:label "is composite element of" ;
    rdfs:comment "Inverse property of hasCompositeElement." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Relates a CompositeDataElement to its SimpleDataElements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse property of hasSimpleElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

:hasInvoice a owl:ObjectProperty ;
    rdfs:label "has invoice" ;
    rdfs:comment "Relates a Message to its Invoice." ;
    rdfs:domain :Message ;
    rdfs:range :Invoice ;
    owl:inverseOf :isInvoiceOf .

:isInvoiceOf a owl:ObjectProperty ;
    rdfs:label "is invoice of" ;
    rdfs:comment "Inverse property of hasInvoice." ;
    rdfs:domain :Invoice ;
    rdfs:range :Message ;
    owl:inverseOf :hasInvoice .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an Invoice to an involved Organization." ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse property of involvesOrganization." ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    owl:inverseOf :involvesOrganization .

:hasAgentRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has agent role assignment" ;
    rdfs:comment "Relates an Organization to its OrganizationRoleAssignment(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :isAgentRoleAssignmentOf .

:isAgentRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is agent role assignment of" ;
    rdfs:comment "Inverse property of hasAgentRoleAssignment." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAgentRoleAssignment .

:hasRole a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has role" ;
    rdfs:comment "Relates an OrganizationRoleAssignment to an AgentRole (e.g., BuyerRole)." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRoleOf .

:isRoleOf a owl:ObjectProperty ;
    rdfs:label "is role of" ;
    rdfs:comment "Inverse property of hasRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :hasRole .

:hasAddress a owl:ObjectProperty, owl:InverseFunctionalProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse property of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasGlobalLocationNumber a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has global location number" ;
    rdfs:comment "Relates an Organization to its GlobalLocationNumber." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    owl:inverseOf :isGlobalLocationNumberOf .

:isGlobalLocationNumberOf a owl:ObjectProperty ;
    rdfs:label "is global location number of" ;
    rdfs:comment "Inverse property of hasGlobalLocationNumber." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    owl:inverseOf :hasGlobalLocationNumber .

:hasHeaderSection a owl:ObjectProperty ;
    rdfs:label "has header section" ;
    rdfs:comment "Relates an Invoice to its HeaderSection." ;
    rdfs:domain :Invoice ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:label "is header section of" ;
    rdfs:comment "Inverse property of hasHeaderSection." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasHeaderSection .

:hasDetailSection a owl:ObjectProperty ;
    rdfs:label "has detail section" ;
    rdfs:comment "Relates an Invoice to its DetailSection." ;
    rdfs:domain :Invoice ;
    rdfs:range :DetailSection ;
    owl:inverseOf :isDetailSectionOf .

:isDetailSectionOf a owl:ObjectProperty ;
    rdfs:label "is detail section of" ;
    rdfs:comment "Inverse property of hasDetailSection." ;
    rdfs:domain :DetailSection ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasDetailSection .

:hasSummarySection a owl:ObjectProperty ;
    rdfs:label "has summary section" ;
    rdfs:comment "Relates an Invoice to its SummarySection." ;
    rdfs:domain :Invoice ;
    rdfs:range :SummarySection ;
    owl:inverseOf :isSummarySectionOf .

:isSummarySectionOf a owl:ObjectProperty ;
    rdfs:label "is summary section of" ;
    rdfs:comment "Inverse property of hasSummarySection." ;
    rdfs:domain :SummarySection ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasSummarySection .

:hasLineItemDetail a owl:ObjectProperty ;
    rdfs:label "has line item detail" ;
    rdfs:comment "Relates a DetailSection to its InvoiceLineItemDetail(s)." ;
    rdfs:domain :DetailSection ;
    rdfs:range :InvoiceLineItemDetail ;
    owl:inverseOf :isLineItemDetailOf .

:isLineItemDetailOf a owl:ObjectProperty ;
    rdfs:label "is line item detail of" ;
    rdfs:comment "Inverse property of hasLineItemDetail." ;
    rdfs:domain :InvoiceLineItemDetail ;
    rdfs:range :DetailSection ;
    owl:inverseOf :hasLineItemDetail .

:hasPrice a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has price" ;
    rdfs:comment "Relates an InvoiceLineItemDetail to its Price." ;
    rdfs:domain :InvoiceLineItemDetail ;
    rdfs:range :Price ;
    owl:inverseOf :isPriceOf .

:isPriceOf a owl:ObjectProperty ;
    rdfs:label "is price of" ;
    rdfs:comment "Inverse property of hasPrice." ;
    rdfs:domain :Price ;
    rdfs:range :InvoiceLineItemDetail ;
    owl:inverseOf :hasPrice .

:hasQuantity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Relates an InvoiceLineItemDetail to its Quantity." ;
    rdfs:domain :InvoiceLineItemDetail ;
    rdfs:range :Quantity ;
    owl:inverseOf :isQuantityOf .

:isQuantityOf a owl:ObjectProperty ;
    rdfs:label "is quantity of" ;
    rdfs:comment "Inverse property of hasQuantity." ;
    rdfs:domain :Quantity ;
    rdfs:range :InvoiceLineItemDetail ;
    owl:inverseOf :hasQuantity .

:hasTaxAmount a owl:ObjectProperty ;
    rdfs:label "has tax amount" ;
    rdfs:comment "Relates a SummarySection to its TaxAmount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :TaxAmount ;
    owl:inverseOf :isTaxAmountOf .

:isTaxAmountOf a owl:ObjectProperty ;
    rdfs:label "is tax amount of" ;
    rdfs:comment "Inverse property of hasTaxAmount." ;
    rdfs:domain :TaxAmount ;
    rdfs:range :SummarySection ;
    owl:inverseOf :hasTaxAmount .

:hasInvoiceAmount a owl:ObjectProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "Relates a SummarySection to its InvoiceAmount." ;
    rdfs:domain :SummarySection ;
    rdfs:range :InvoiceAmount ;
    owl:inverseOf :isInvoiceAmountOf .

:isInvoiceAmountOf a owl:ObjectProperty ;
    rdfs:label "is invoice amount of" ;
    rdfs:comment "Inverse property of hasInvoiceAmount." ;
    rdfs:domain :InvoiceAmount ;
    rdfs:range :SummarySection ;
    owl:inverseOf :hasInvoiceAmount .

:hasReferenceNumber a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Relates a HeaderSection to its ReferenceNumber." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :ReferenceNumber ;
    owl:inverseOf :isReferenceNumberOf .

:isReferenceNumberOf a owl:ObjectProperty ;
    rdfs:label "is reference number of" ;
    rdfs:comment "Inverse property of hasReferenceNumber." ;
