    rdfs:domain :CompositeDataElement ;
    rdfs:range :Segment ;
    owl:inverseOf :hasCompositeElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Relates a CompositeDataElement to its SimpleDataElements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement ;
    owl:inverseOf :isSimpleElementOf .

:isSimpleElementOf a owl:ObjectProperty ;
    rdfs:label "is simple element of" ;
    rdfs:comment "Inverse property of hasSimpleElement." ;
    rdfs:domain :SimpleDataElement ;
    rdfs:range :CompositeDataElement ;
    owl:inverseOf :hasSimpleElement .

:hasInvoice a owl:ObjectProperty ;
    rdfs:label "has invoice" ;
    rdfs:comment "Relates a Message to its Invoice." ;
    rdfs:domain :Message ;
    rdfs:range :Invoice ;
    owl:inverseOf :isInvoiceOf .

:isInvoiceOf a owl:ObjectProperty ;
    rdfs:label "is invoice of" ;
    rdfs:comment "Inverse property of hasInvoice." ;
    rdfs:domain :Invoice ;
    rdfs:range :Message ;
    owl:inverseOf :hasInvoice .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Relates an Invoice to an involved Organization." ;
    rdfs:domain :Invoice ;
    rdfs:range :Organization ;
    owl:inverseOf :isOrganizationInvolvedIn .

:isOrganizationInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is organization involved in" ;
    rdfs:comment "Inverse property of involvesOrganization." ;
    rdfs:domain :Organization ;
    rdfs:range :Invoice ;
    owl:inverseOf :involvesOrganization .

:hasAgentRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has agent role assignment" ;
    rdfs:comment "Relates an Organization to its OrganizationRoleAssignment(s)." ;
    rdfs:domain :Organization ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :isAgentRoleAssignmentOf .

:isAgentRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is agent role assignment of" ;
    rdfs:comment "Inverse property of hasAgentRoleAssignment." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAgentRoleAssignment .

:hasRole a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has role" ;
    rdfs:comment "Relates an OrganizationRoleAssignment to an AgentRole (e.g., BuyerRole)." ;
    rdfs:domain :OrganizationRoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isRoleOf .

:isRoleOf a owl:ObjectProperty ;
    rdfs:label "is role of" ;
    rdfs:comment "Inverse property of hasRole." ;
    rdfs:domain :AgentRole ;
    rdfs:range :OrganizationRoleAssignment ;
    owl:inverseOf :hasRole .

:hasAddress a owl:ObjectProperty, owl:InverseFunctionalProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Relates an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Inverse property of hasAddress." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasGlobalLocationNumber a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has global location number" ;
    rdfs:comment "Relates an Organization to its GlobalLocationNumber." ;
    rdfs:domain :Organization ;
    rdfs:range :GlobalLocationNumber ;
    owl:inverseOf :isGlobalLocationNumberOf .

:isGlobalLocationNumberOf a owl:ObjectProperty ;
    rdfs:label "is global location number of" ;
    rdfs:comment "Inverse property of hasGlobalLocationNumber." ;
    rdfs:domain :GlobalLocationNumber ;
    rdfs:range :Organization ;
    owl:inverseOf :hasGlobalLocationNumber .

:hasHeaderSection a owl:ObjectProperty ;
    rdfs:label "has header section" ;
    rdfs:comment "Relates an Invoice to its HeaderSection." ;
    rdfs:domain :Invoice ;
    rdfs:range :HeaderSection ;
    owl:inverseOf :isHeaderSectionOf .

:isHeaderSectionOf a owl:ObjectProperty ;
    rdfs:label "is header section of" ;
    rdfs:comment "Inverse property of hasHeaderSection." ;
    rdfs:domain :HeaderSection ;
    rdfs:range :Invoice ;
    owl:inverseOf :hasHeaderSection .

:hasDetailSection a owl:ObjectProperty ;
